with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , ADD_STATUS as ADDENDUM_STATUS
        , REF_BILL_ID as REFERENCED_BILL_REFERENCE
        , 'BJAZ_HM_BILL_DETAIL_OCR' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_bill_detail_ocr') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ADDENDUM_STATUS end) as ADDENDUM_STATUS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then REFERENCED_BILL_REFERENCE end) as REFERENCED_BILL_REFERENCE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when ADDENDUM_STATUS is not null or REFERENCED_BILL_REFERENCE is not null
                     then md5(upper(coalesce(cast(ADDENDUM_STATUS as varchar), '') || '|' || coalesce(cast(REFERENCED_BILL_REFERENCE as varchar), '')))
                end as SAT_CLAIM_BILL_DIGITISATION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_BILL_DIGITISATION_HASHDIFF is not null
